// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SignerMaker maker;
    MockERC20 token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new SignerMaker();
        token = new MockERC20();
    }

    function testFuzz_property(uint256 nonce, uint256 duration, uint256 expiration, address recipient, address third) public {
        vm.assume(recipient != address(0) && third != address(0));
        vm.assume(recipient != address(maker) && third != address(maker));
        vm.assume(recipient != third);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration % 1000 days,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        vm.warp(1000);
        order.expiration = 1000 + (expiration % 1_000_000) + order.duration + 1;

        uint256[] memory floorIds = new uint256[](0);
        c.fillOrder(order, new bytes(0), floorIds);

        uint256 tokenId = uint256(c.hashOrder(order));

        // current holder passes the token on
        vm.prank(address(maker));
        c.transferFrom(address(maker), recipient, tokenId);

        // RULE: any recipient of a transferFrom may transfer the token onward
        vm.prank(recipient);
        bool ok;
        try c.transferFrom(recipient, third, tokenId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract SignerMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
